#!/usr/bin/env bash\nset -e\n# Load environment variables if .env exists\nif [ -f "$(dirname "$0")/../config/.env" ]; then\n  export $(grep -v '^#' "$(dirname "$0")/../config/.env" | xargs)\nfi\nBACKUP_DIR="${BACKUP_DIR:-./backups}"\ncd "$BACKUP_DIR"\n# Keep only the 7 most recent backups, delete older ones\nls -t backup_*.sql 2>/dev/null | tail -n +8 | xargs -d '\n' rm -f --\necho "Old backups cleaned, kept latest 7 files."\n# Reminder: make this script executable\n# chmod +x $(basename "$0")\n